package org.diy.liferecorder;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.util.*;
import java.io.IOException;

/** SQLite event state, atomic evidence, confirmed memory retrieval and correction history. */
final class LifeMemory {
    static boolean enabled(RecordStore db){return db.context.getSharedPreferences("understanding",0).getBoolean("memory_enabled",true);}
    static void checkPolicy(RecordStore db,JSONObject snapshot)throws IOException{if(snapshot.optBoolean("memory_enabled",true)!=enabled(db))throw new IOException("记忆使用设置已改变，请重新发起请求");}
    static boolean policyChanged(RecordStore db,JSONObject input){JSONObject policy=input.optJSONObject("memory_context");if(policy==null)policy=input.optJSONObject("review_snapshot");if(policy==null)policy=input;return policy.has("memory_enabled")&&policy.optBoolean("memory_enabled")!=enabled(db);}
    static void schema(SQLiteDatabase db){
        db.execSQL("CREATE TABLE life_events(id TEXT PRIMARY KEY,title TEXT NOT NULL,summary TEXT NOT NULL,state TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated INTEGER NOT NULL)");
        db.execSQL("CREATE TABLE event_units(unit_id TEXT PRIMARY KEY,event_id TEXT NOT NULL,source TEXT NOT NULL,payload TEXT NOT NULL,FOREIGN KEY(event_id) REFERENCES life_events(id) ON DELETE CASCADE,FOREIGN KEY(source) REFERENCES audio(id) ON DELETE CASCADE)");
        db.execSQL("CREATE INDEX event_source_idx ON event_units(source)");
        db.execSQL("CREATE TABLE atomic_facts(id TEXT PRIMARY KEY,event_id TEXT NOT NULL,source TEXT NOT NULL,unit_id TEXT NOT NULL,type TEXT NOT NULL,text TEXT NOT NULL,quote TEXT NOT NULL,memory_id TEXT,state TEXT NOT NULL DEFAULT 'unconfirmed',FOREIGN KEY(event_id) REFERENCES life_events(id) ON DELETE CASCADE,FOREIGN KEY(source) REFERENCES audio(id) ON DELETE CASCADE,FOREIGN KEY(memory_id) REFERENCES facts(id) ON DELETE SET NULL)");
        db.execSQL("CREATE TABLE memory_links(id TEXT PRIMARY KEY,event_id TEXT NOT NULL,memory_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'review',FOREIGN KEY(event_id) REFERENCES life_events(id) ON DELETE CASCADE,FOREIGN KEY(memory_id) REFERENCES facts(id) ON DELETE CASCADE,UNIQUE(event_id,memory_id))");
        db.execSQL("CREATE TABLE life_reviews(id TEXT PRIMARY KEY,kind TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,result TEXT NOT NULL,evidence TEXT NOT NULL,created INTEGER NOT NULL,stale INTEGER NOT NULL DEFAULT 0)");
        db.execSQL("CREATE TABLE life_feedback(id TEXT PRIMARY KEY,source TEXT,event_id TEXT,energy INTEGER,note TEXT NOT NULL,accuracy TEXT NOT NULL,created INTEGER NOT NULL,FOREIGN KEY(source) REFERENCES audio(id) ON DELETE CASCADE,FOREIGN KEY(event_id) REFERENCES life_events(id) ON DELETE CASCADE)");
        db.execSQL("CREATE TABLE correction_history(id TEXT PRIMARY KEY,target TEXT NOT NULL,kind TEXT NOT NULL,before_text TEXT NOT NULL,after_text TEXT NOT NULL,created INTEGER NOT NULL)");
        db.execSQL("CREATE VIRTUAL TABLE memory_fts USING fts4(memory_id,text,tokenize=unicode61)");
    }
    static String tokens(String text){StringBuilder out=new StringBuilder(text.replaceAll("[^\\p{L}\\p{N}]"," "));for(int i=0;i+1<text.length();i++)if(Character.UnicodeScript.of(text.charAt(i))==Character.UnicodeScript.HAN&&Character.UnicodeScript.of(text.charAt(i+1))==Character.UnicodeScript.HAN)out.append(' ').append(text.substring(i,i+2));return out.toString();}
    static void index(RecordStore db,String id)throws Exception{db.getWritableDatabase().delete("memory_fts","memory_id=?",new String[]{id});JSONArray rows=db.rows("SELECT text FROM facts WHERE id=? AND state='accepted'",id);if(rows.length()>0){ContentValues v=new ContentValues();v.put("memory_id",id);v.put("text",tokens(rows.getJSONObject(0).getString("text")));db.getWritableDatabase().insertOrThrow("memory_fts",null,v);}}
    static JSONArray retrieve(RecordStore db,String query)throws Exception{
        LinkedHashSet<String> terms=new LinkedHashSet<>();for(String t:tokens(query).split("\\s+"))if(t.length()>=2&&t.length()<=30){terms.add(t);if(terms.size()>=64)break;}if(terms.isEmpty())return new JSONArray();StringBuilder match=new StringBuilder();for(String term:terms){if(match.length()>0)match.append(" OR ");match.append('"').append(term).append('"');}
        return db.rows("SELECT DISTINCT f.id,f.text,f.source FROM memory_fts m JOIN facts f ON f.id=m.memory_id JOIN audio a ON a.id=f.source WHERE memory_fts MATCH ? AND f.state='accepted' ORDER BY f.created DESC LIMIT 8",match.toString());
    }
    static JSONObject context(RecordStore db,JSONObject snapshot)throws Exception{
        JSONArray units=snapshot.getJSONArray("units"),sources=snapshot.getJSONArray("sources");long start=sources.getJSONObject(0).getLong("created"),end=sources.getJSONObject(sources.length()-1).getLong("created");Set<String> selected=new HashSet<>();for(int i=0;i<sources.length();i++)selected.add(sources.getJSONObject(i).getString("source_id"));
        JSONArray events=db.rows("SELECT * FROM life_events WHERE end>=? AND start<=? AND state<>'stale' ORDER BY end DESC LIMIT 8",String.valueOf(start-900000),String.valueOf(end+900000));JSONArray states=new JSONArray();
        for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);JSONArray rows=db.rows("SELECT payload,source FROM event_units WHERE event_id=?",e.getString("id")),old=new JSONArray();for(int n=0;n<rows.length();n++)if(!selected.contains(rows.getJSONObject(n).getString("source")))old.put(new JSONObject(rows.getJSONObject(n).getString("payload")));JSONArray prior=db.rows("SELECT * FROM atomic_facts WHERE event_id=? ORDER BY id",e.getString("id")),kept=new JSONArray();for(int n=0;n<prior.length();n++)if(!selected.contains(prior.getJSONObject(n).getString("source")))kept.put(prior.getJSONObject(n));e.put("units",old).put("facts",kept);states.put(e);}
        JSONArray memories=enabled(db)?retrieve(db,TranscriptDocument.text(units)):new JSONArray();JSONObject out=new JSONObject().put("memory_enabled",enabled(db)).put("events",states).put("confirmed_memories",memories);if(out.toString().length()>60000)throw new IOException("连续事件上下文过大，请先结束或拆分事件后分析");return out;
    }
    static void checkContext(RecordStore db,JSONObject context)throws Exception{
        checkPolicy(db,context);
        JSONArray events=context.getJSONArray("events");for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);JSONArray now=db.rows("SELECT revision FROM life_events WHERE id=?",e.getString("id"));if(now.length()==0||now.getJSONObject(0).getLong("revision")!=e.getLong("revision"))throw new IOException("关联事件已更新，请重新分析");}
        JSONArray boundary=context.optJSONArray("boundary_context");if(boundary!=null)for(int i=0;i<boundary.length();i++){JSONObject unit=boundary.getJSONObject(i);if(db.audio(unit.getString("source_id")).optLong("transcript_revision")!=unit.optLong("source_revision"))throw new IOException("边界上下文已更新，请重新分析");}
        JSONArray memories=context.getJSONArray("confirmed_memories");for(int i=0;i<memories.length();i++){JSONObject m=memories.getJSONObject(i);JSONArray now=db.rows("SELECT text,state FROM facts WHERE id=?",m.getString("id"));if(now.length()==0||!now.getJSONObject(0).optString("state").equals("accepted")||!now.getJSONObject(0).optString("text").equals(m.getString("text")))throw new IOException("关联记忆已纠正，请重新分析");}
    }
    static void expand(JSONObject extracted,JSONObject context)throws Exception{
        Map<String,JSONObject> events=new HashMap<>();JSONArray old=context.getJSONArray("events");for(int i=0;i<old.length();i++)events.put(old.getJSONObject(i).getString("id"),old.getJSONObject(i));Set<String> used=new HashSet<>();JSONArray parts=extracted.getJSONArray("paragraphs");
        for(int i=0;i<parts.length();i++){JSONObject p=parts.getJSONObject(i);String action=p.optString("action","NEW_EVENT"),event=p.optString("event_id");if(!action.matches("CONTINUE|NEW_EVENT|CLOSE_EVENT|SPLIT"))throw new IOException("事件动作无效");
            if(!action.equals("NEW_EVENT")){JSONObject existing=events.get(event);if(existing==null||!used.add(event))throw new IOException("事件引用无效或重复");JSONArray merged=new JSONArray(),before=existing.getJSONArray("units"),current=p.getJSONArray("units");long first=Long.MAX_VALUE,last=0;for(int n=0;n<current.length();n++){JSONObject u=current.getJSONObject(n);first=Math.min(first,absolute(u,false));last=Math.max(last,absolute(u,true));}
                if(first>existing.getLong("end")+900000||last<existing.getLong("start")-900000)throw new IOException("事件时间不连续");
                if(!action.equals("SPLIT")){ArrayList<JSONObject> sorted=new ArrayList<>();for(int n=0;n<before.length();n++)sorted.add(before.getJSONObject(n));for(int n=0;n<current.length();n++)sorted.add(current.getJSONObject(n));sorted.sort((a,b)->Long.compare(absolute(a,false),absolute(b,false)));for(JSONObject u:sorted)merged.put(u);p.put("units",merged).put("text",TranscriptDocument.text(merged));}
                p.put("prior_facts",existing.getJSONArray("facts"));
            }
        }
    }
    static long absolute(JSONObject u,boolean end){return u.optLong("source_created")+(u.optBoolean("timed")?u.optLong(end?"end_ms":"start_ms"):end?u.optLong("source_duration"):0);}
    static void save(RecordStore db,JSONObject result,JSONObject context)throws Exception{
        checkContext(db,context);SQLiteDatabase sql=db.getWritableDatabase();JSONArray sources=result.getJSONArray("sources"),parts=result.getJSONArray("paragraphs"),facts=result.getJSONArray("facts");Set<String> affected=new HashSet<>();
        for(int i=0;i<sources.length();i++){String source=sources.getJSONObject(i).getString("source_id");JSONArray old=db.rows("SELECT DISTINCT event_id FROM event_units WHERE source=?",source);for(int n=0;n<old.length();n++)affected.add(old.getJSONObject(n).getString("event_id"));sql.delete("atomic_facts","source=?",new String[]{source});sql.delete("event_units","source=?",new String[]{source});}
        Map<String,String> eventByUnit=new HashMap<>();
        for(int i=0;i<parts.length();i++){JSONObject p=parts.getJSONObject(i);String action=p.optString("action","NEW_EVENT"),id=p.optString("event_id");if(action.equals("SPLIT")){sql.execSQL("UPDATE life_events SET state='closed',revision=revision+1 WHERE id=?",new Object[]{id});affected.add(id);id="";}if(action.equals("NEW_EVENT")||id.isEmpty())id=UUID.randomUUID().toString();p.put("saved_event_id",id);JSONArray units=p.getJSONArray("units");long start=Long.MAX_VALUE,end=0;
            for(int n=0;n<units.length();n++){JSONObject u=units.getJSONObject(n);start=Math.min(start,absolute(u,false));end=Math.max(end,absolute(u,true));eventByUnit.put(u.getString("unit_id"),id);}
            JSONArray old=db.rows("SELECT revision FROM life_events WHERE id=?",id);ContentValues v=new ContentValues();v.put("id",id);v.put("title",p.getString("title"));v.put("summary",p.getString("summary"));v.put("state",action.equals("CLOSE_EVENT")||i<parts.length()-1?"closed":"open");v.put("start",start);v.put("end",end);v.put("revision",old.length()==0?1:old.getJSONObject(0).optLong("revision")+1);v.put("updated",System.currentTimeMillis());p.put("saved_event_revision",old.length()==0?1:old.getJSONObject(0).optLong("revision")+1);if(old.length()==0)sql.insertOrThrow("life_events",null,v);else sql.update("life_events",v,"id=?",new String[]{id});
            for(int n=0;n<units.length();n++){JSONObject u=units.getJSONObject(n);if(!u.has("content_kind"))u.put("content_kind",p.optString("content_kind","meaningful"));ContentValues unit=new ContentValues();unit.put("unit_id",u.getString("unit_id"));unit.put("source",u.getString("source_id"));unit.put("event_id",id);unit.put("payload",u.toString());sql.insertWithOnConflict("event_units",null,unit,SQLiteDatabase.CONFLICT_REPLACE);}
            ContentFilter.save(db,id,p);affected.remove(id);
        }
        for(int i=0;i<facts.length();i++){JSONObject f=facts.getJSONObject(i);String event=eventByUnit.get(f.getString("unit_id"));ContentValues v=new ContentValues();v.put("id",UUID.randomUUID().toString());v.put("event_id",event);v.put("source",f.getString("source_id"));v.put("unit_id",f.getString("unit_id"));v.put("type",f.getString("type"));v.put("text",f.getString("text"));v.put("quote",f.getString("quote"));JSONArray memory=db.rows("SELECT id FROM facts WHERE source=? AND text=?",f.getString("source_id"),f.getString("text"));if(memory.length()>0)v.put("memory_id",memory.getJSONObject(0).getString("id"));sql.insertOrThrow("atomic_facts",null,v);}
        for(int i=0;i<parts.length();i++){String event=parts.getJSONObject(i).getString("saved_event_id");JSONArray memories=context.getJSONArray("confirmed_memories");for(int n=0;n<memories.length();n++){ContentValues v=new ContentValues();v.put("id",UUID.randomUUID().toString());v.put("event_id",event);v.put("memory_id",memories.getJSONObject(n).getString("id"));sql.insertWithOnConflict("memory_links",null,v,SQLiteDatabase.CONFLICT_IGNORE);}}
        for(String event:affected){sql.execSQL("UPDATE life_events SET state='stale',revision=revision+1 WHERE id=?",new Object[]{event});}sql.execSQL("DELETE FROM life_events WHERE NOT EXISTS(SELECT 1 FROM event_units WHERE event_id=life_events.id)");sql.execSQL("UPDATE life_events SET state='closed',revision=revision+1 WHERE state='open' AND end<?",new Object[]{sources.getJSONObject(0).getLong("created")-900000});sql.execSQL("UPDATE life_reviews SET stale=1");
    }
    static void invalidate(RecordStore db,String source)throws Exception{SQLiteDatabase sql=db.getWritableDatabase();sql.execSQL("UPDATE life_events SET state='stale',revision=revision+1 WHERE id IN (SELECT event_id FROM event_units WHERE source=?)",new Object[]{source});sql.execSQL("UPDATE life_reviews SET stale=1");sql.execSQL("DELETE FROM memory_fts WHERE memory_id IN (SELECT id FROM facts WHERE source=?)",new Object[]{source});}
    static void history(RecordStore db,String target,String kind,String before,String after){ContentValues v=new ContentValues();v.put("id",UUID.randomUUID().toString());v.put("target",target);v.put("kind",kind);v.put("before_text",before);v.put("after_text",after);v.put("created",System.currentTimeMillis());db.getWritableDatabase().insertOrThrow("correction_history",null,v);}
    static void checkReading(RecordStore db,JSONObject analysis)throws Exception{AnalysisPipeline.checkCurrent(db,analysis);JSONArray parts=analysis.getJSONArray("paragraphs");for(int i=0;i<parts.length();i++){JSONObject p=parts.getJSONObject(i);if(p.optString("saved_event_id").isEmpty())continue;JSONArray now=db.rows("SELECT state,revision FROM life_events WHERE id=?",p.getString("saved_event_id"));if(now.length()==0||now.getJSONObject(0).optString("state").equals("stale")||p.optLong("saved_event_revision",now.getJSONObject(0).optLong("revision"))!=now.getJSONObject(0).optLong("revision"))throw new IOException("事件或来源已更新");}}
    static void requireRevision(RecordStore db,JSONObject event)throws Exception{JSONArray now=db.rows("SELECT revision FROM life_events WHERE id=?",event.getString("id"));if(now.length()==0||now.getJSONObject(0).optLong("revision")!=event.optLong("revision"))throw new IOException("事件已更新，请刷新后纠正");}
    static void split(RecordStore db,JSONObject event,List<JSONObject> units,int from)throws Exception{
        SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{requireRevision(db,event);String old=event.getString("id"),id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("title",event.getString("title")+" · 后半段");v.put("summary","事件边界已人工纠正，请重新分析来源以更新总结。");v.put("state","stale");v.put("start",absolute(units.get(from),false));v.put("end",event.getLong("end"));v.put("updated",System.currentTimeMillis());sql.insertOrThrow("life_events",null,v);
            for(int i=from;i<units.size();i++){String unit=units.get(i).getString("unit_id");sql.execSQL("UPDATE event_units SET event_id=? WHERE unit_id=?",new Object[]{id,unit});sql.execSQL("UPDATE atomic_facts SET event_id=? WHERE unit_id=?",new Object[]{id,unit});}
            sql.execSQL("UPDATE life_events SET end=?,state='stale',summary='事件边界已人工纠正，请重新分析来源以更新总结。',revision=revision+1 WHERE id=?",new Object[]{absolute(units.get(from-1),true),old});history(db,old,"event_split",event.toString(),id);sql.execSQL("UPDATE life_reviews SET stale=1");sql.execSQL("UPDATE audio SET analysis='' WHERE id IN (SELECT source FROM event_units WHERE event_id IN (?,?))",new Object[]{old,id});sql.setTransactionSuccessful();}finally{sql.endTransaction();}
    }
    static void merge(RecordStore db,JSONObject first,JSONObject second)throws Exception{
        SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{requireRevision(db,first);requireRevision(db,second);String id=first.getString("id"),old=second.getString("id");sql.execSQL("UPDATE event_units SET event_id=? WHERE event_id=?",new Object[]{id,old});sql.execSQL("UPDATE atomic_facts SET event_id=? WHERE event_id=?",new Object[]{id,old});sql.execSQL("UPDATE life_events SET start=?,end=?,state='stale',summary='事件已人工合并，请重新分析来源以更新总结。',revision=revision+1 WHERE id=?",new Object[]{Math.min(first.getLong("start"),second.getLong("start")),Math.max(first.getLong("end"),second.getLong("end")),id});sql.delete("life_events","id=?",new String[]{old});history(db,id,"event_merge",first.toString()+second.toString(),id);sql.execSQL("UPDATE life_reviews SET stale=1");sql.execSQL("UPDATE audio SET analysis='' WHERE id IN (SELECT source FROM event_units WHERE event_id=?)",new Object[]{id});sql.setTransactionSuccessful();}finally{sql.endTransaction();}
    }

}
